function resolveOperation(identifier) {
  const key = String(identifier || "").trim().replace(/^client\./, "");
  if (!key) return null;
  if (BY_OPERATION_ID.has(key)) return BY_OPERATION_ID.get(key);
  if (BY_MEMBER.has(key)) return BY_MEMBER.get(key);
  if (BY_FLAT_MEMBER.has(key)) return BY_FLAT_MEMBER.get(key);
  const lower = key.toLowerCase();
  for (const op of OPERATIONS) {
    if (
      op.operation_id.toLowerCase() === lower ||
      op.member.toLowerCase() === lower ||
      op.flat_member.toLowerCase() === lower ||
      op.path.toLowerCase() === lower ||
      `${op.method} ${op.path}`.toLowerCase() === lower
    ) {
      return op;
    }
  }
  return null;
}

function handleSearchDocs(args) {
  const query = String(args?.query || "").trim().toLowerCase();
  const methodFilter = String(args?.method || "").trim().toUpperCase();
  const tagFilter = String(args?.tag || "").trim().toLowerCase();
  const limit = Math.max(1, Math.min(50, Number(args?.limit) || 10));
  const tokens = query ? query.split(/\s+/).filter(Boolean) : [];

  const scored = [];
  for (const op of OPERATIONS) {
    if (methodFilter && op.method !== methodFilter) continue;
    if (
      tagFilter &&
      op.resource.toLowerCase() !== tagFilter &&
      !(op.tags || []).some((t) => String(t).toLowerCase() === tagFilter)
    ) {
      continue;
    }
    const haystack = [
      op.operation_id,
      op.member,
      op.flat_member,
      op.method,
      op.path,
      op.summary,
      op.description,
      ...(op.tags || []),
    ]
      .join(" ")
      .toLowerCase();

    let score = 0;
    if (tokens.length === 0) {
      score = 1;
    } else {
      for (const token of tokens) {
        if (op.operation_id.toLowerCase() === token || op.member.toLowerCase() === token) {
          score += 10;
        } else if (op.operation_id.toLowerCase().includes(token) || op.member.toLowerCase().includes(token)) {
          score += 6;
        } else if (op.path.toLowerCase().includes(token)) {
          score += 4;
        } else if (haystack.includes(token)) {
          score += 2;
        }
      }
    }
    if (score > 0) {
      scored.push({
        score,
        operation_id: op.operation_id,
        member: `client.${op.member}`,
        method: op.method,
        path: op.path,
        summary: op.summary,
        read_only: op.read_only,
        signature: op.signature,
      });
    }
  }

  scored.sort((a, b) => b.score - a.score || a.operation_id.localeCompare(b.operation_id));
  const matches = scored.slice(0, limit);
  const payload = {
    schema: "omniwrap.typescript-sdk-mcp/v1",
    query: args?.query || "",
    total_matches: scored.length,
    matches,
  };
  return {
    content: [{ type: "text", text: JSON.stringify(payload) }],
    structuredContent: payload,
    isError: false,
  };
}

function handleListApiEndpoints(args) {
  const methodFilter = String(args?.method || "").trim().toUpperCase();
  const resourceFilter = String(args?.resource || "").trim().toLowerCase();
  const readOnlyFilter = typeof args?.read_only === "boolean" ? args.read_only : null;

  const endpoints = OPERATIONS.filter((op) => {
    if (methodFilter && op.method !== methodFilter) return false;
    if (resourceFilter && op.resource.toLowerCase() !== resourceFilter) return false;
    if (readOnlyFilter !== null && op.read_only !== readOnlyFilter) return false;
    return true;
  }).map((op) => ({
    operation_id: op.operation_id,
    member: `client.${op.member}`,
    method: op.method,
    path: op.path,
    resource: op.resource,
    read_only: op.read_only,
    idempotent: op.idempotent,
    summary: op.summary,
  }));

  const payload = {
    schema: "omniwrap.typescript-sdk-mcp/v1",
    contract_sha256: CONTRACT_SHA256,
    total: endpoints.length,
    endpoints,
  };
  return {
    content: [{ type: "text", text: JSON.stringify(payload) }],
    structuredContent: payload,
    isError: false,
  };
}

function handleGetApiEndpointSchema(args) {
  const target = args?.operation_id || args?.endpoint || args?.operationId || args?.name;
  const op = resolveOperation(target);
  if (!op) {
    const errPayload = {
      error: "operation-not-found",
      requested: target || null,
      available_operations: OPERATIONS.map((item) => item.operation_id),
    };
    return {
      content: [{ type: "text", text: JSON.stringify(errPayload) }],
      structuredContent: errPayload,
      isError: true,
    };
  }
  const payload = {
    schema: "omniwrap.typescript-sdk-mcp/v1",
    operation_id: op.operation_id,
    member: `client.${op.member}`,
    flat_member: `client.${op.flat_member}`,
    method: op.method,
    path: op.path,
    resource: op.resource,
    summary: op.summary,
    description: op.description,
    read_only: op.read_only,
    idempotent: op.idempotent,
    signature: op.signature,
    parameters: op.parameters,
    request_body: op.request_body,
    responses: op.responses,
  };
  return {
    content: [{ type: "text", text: JSON.stringify(payload) }],
    structuredContent: payload,
    isError: false,
  };
}

